"// recordPlayHistory saves playback history to SQLite.
// Uses expectedNextPlayTime to record the estimated real play time instead of
// the pre-fetch request time (Liquidsoap requests tracks ahead of time).
// play_status lifecycle: na_fila → tocando → executada (sequentially, never altering older records)
// The most recent item is always 'na_ponta' (the tip), previous 'na_ponta' becomes 'executada'.
func recordPlayHistory(item PlayItem) {
	if DB == nil {
		return
	}

	now := time.Now()
	playTime := now

	// If expectedNextPlayTime is set and in the future, use it as the real play time.
	// Otherwise use now (first track after startup, or gap in playback).
	// Limit the future offset to 15 minutes to heal from skips/drift.
	if !expectedNextPlayTime.IsZero() && expectedNextPlayTime.After(now) {
		if expectedNextPlayTime.Sub(now) > 15*time.Minute {
			LogLocal("WARNING", "[Scheduler] Playback drift detected (%s is >15m in future). Resetting schedule time to now.", expectedNextPlayTime.Format("15:04:05"))
			playTime = now
		} else {
			playTime = expectedNextPlayTime
		}
	}"

