func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	fmt.Println("=== PLANNED SLOTS BY STATUS ===")
	rows, err := db.Query("SELECT play_date, status, COUNT(*) FROM planned_commercial_slots GROUP BY play_date, status")
	if err == nil {
		for rows.Next() {
			var date, status string
			var count int
			_ = rows.Scan(&date, &status, &count)
			fmt.Printf("Date: %s, Status: %s, Count: %d\n", date, status, count)
		}
		rows.Close()
	}

	fmt.Println("\n=== ACTIVE COMMERCIALS & EVENTS ===")
	var commsCount int
	_ = db.QueryRow("SELECT COUNT(*) FROM commercials_and_events").Scan(&commsCount)
	fmt.Printf("Total Commercials/Events in library: %d\n", commsCount)
}
"

"package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
)

type DiagnosticBlockStructure struct {
	BlockNumber   int    `json:"block_number"`
	BlockTime     string `json:"block_time"`
	Structure     string `json:"structure"`
	TotalQuantity int    `json:"total_quantity"`
	TotalDuration int    `json:"total_duration"`
	LimitDuration int    `json:"limit_duration"`
	ExceedsLimit  bool   `json:"exceeds_limit"`
}

type DiagnosticResponse struct {
	BlockStructures []DiagnosticBlockStructure `json:"block_structures"`
}

func main() {
	resp, err := http.Get("http://localhost:5005/api/diagnostics?date=today")
	if err != nil {
		fmt.Println("failed to fetch diagnostics:", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	var data DiagnosticResponse
	if err := json.NewDecoder(resp.Body).Decode(&data); err != nil {
		fmt.Println("failed to decode json:", err)
		os.Exit(1)
	}

	fmt.Printf("%-8s | %-10s | %-50s | %-6s | %-8s\n", "Block ID", "Time", "Structure", "Qty", "Duration")
	fmt.Println("-----------------------------------------------------------------------------------------")
	for _, b := range data.BlockStructures {
		fmt.Printf("#%-7d | %-10s | %-50s | %-6d | %-8d\n", b.BlockNumber, b.BlockTime, b.Structure, b.TotalQuantity, b.TotalDuration)
	}
}
"

