"package main

import (
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	fmt.Println("=== STORE INFO ===")
	var id, tenantID, name, number, city, state, timezone, lastSync string
	var audioGridID, videoGridID sql.NullString
	var hasAudio, hasVideo int
	err = db.QueryRow("SELECT id, tenant_id, store_name, store_number, city, state, timezone, has_audio, has_video, audio_grid_id, video_grid_id, last_sync FROM store_info").Scan(
		&id, &tenantID, &name, &number, &city, &state, &timezone, &hasAudio, &hasVideo, &audioGridID, &videoGridID, &lastSync,
	)
	if err != nil {
		fmt.Println("store_info error:", err)
	} else {
		fmt.Printf("Store ID: %s\nStore Name: %s\nStore Number: %s\nTimezone: %s\nLast Sync: %s\n", id, name, number, timezone, lastSync)
		fmt.Printf("Audio Grid ID in store_info: %s (Valid: %t)\n", audioGridID.String, audioGridID.Valid)
	}

	fmt.Println("\n=== ALL GRIDS IN weekly_master_grids ===")
	rows, err := db.Query("SELECT id, name FROM weekly_master_grids")
	if err != nil {
		fmt.Println("query error:", err)
	} else {
		for rows.Next() {
			var gridID, gridName string
			if errScan := rows.Scan(&gridID, &gridName); errScan == nil {
				fmt.Printf("Grid ID: %s, Name: %s\n", gridID, gridName)
			}
		}
		rows.Close()
	}

	// Print time
	fmt.Printf("\nGo time.Now(): %v\n", time.Now())
	fmt.Printf("Go UTC time: %v\n", time.Now().UTC())
}
"

