"package main

import (
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

// Declare these to match scheduler's expectations if needed, but we can just import scheduler
// Or we can just call it from our code by importing the package. Since we're in package main in the same directory,
// we can't easily import "main" from another file unless we run both files together.
// So let's write a script that runs the DB cleaning and then prints the results after calling the PreDistributeCommercials function.
// Since PreDistributeCommercials is in scheduler.go (package main), we can run "go run clear_slots.go scheduler.go db.go watchdog.go config.go decrypter.go" etc., or we can just make it package main, open the DB, clean it, and run go run on both files.
// Let's look at what files are needed for scheduler.go to compile.
// Actually, it's easier to write a script that just deletes the slots, then we restart the daemon, which will automatically run PreDistributeCommercials on startup!
// Let's check main.go to see if it runs PreDistributeCommercials or scheduler on startup.

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	dateStr := "2026-06-12"
	fmt.Printf("Clearing all planned slots and play history for %s...\n", dateStr)

	res1, err := db.Exec("DELETE FROM planned_commercial_slots WHERE play_date = $1", dateStr)
	if err != nil {
		fmt.Println("Error deleting planned slots:", err)
	} else {
		affected, _ := res1.RowsAffected()
		fmt.Printf("Deleted %d planned slots.\n", affected)
	}

	res2, err := db.Exec("DELETE FROM play_history WHERE played_at >= $1", dateStr + " 00:00:00")
	if err != nil {
		fmt.Println("Error deleting play history:", err)
	} else {
		affected, _ := res2.RowsAffected()
		fmt.Printf("Deleted %d play history entries.\n", affected)
	}
}
