"package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
)

type DiagnosticBlockStructure struct {
	BlockNumber   int    `json:"block_number"`
	BlockTime     string `json:"block_time"`
	Structure     string `json:"structure"`
	TotalQuantity int    `json:"total_quantity"`
	TotalDuration int    `json:"total_duration"`
	LimitDuration int    `json:"limit_duration"`
	ExceedsLimit  bool   `json:"exceeds_limit"`
	BlockType     string `json:"block_type"`
}

type DiagnosticResponse struct {
	BlockStructures []DiagnosticBlockStructure `json:"block_structures"`
}

func main() {
	resp, err := http.Get("http://localhost:5005/api/diagnostics?date=today")
	if err != nil {
		fmt.Println("Error fetching API:", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		fmt.Println("Error reading body:", err)
		os.Exit(1)
	}

	var data DiagnosticResponse
	if err := json.Unmarshal(body, &data); err != nil {
		fmt.Println("Error unmarshaling JSON:", err)
		os.Exit(1)
	}

	fmt.Println("=== FIRST 10 BLOCKS FROM API ===")
	limit := 10
	if len(data.BlockStructures) < limit {
		limit = len(data.BlockStructures)
	}
	for i := 0; i < limit; i++ {
		bs := data.BlockStructures[i]
		fmt.Printf("Block #%d [%s] Time: %s | Structure: %s | Qty: %d | Dur: %d | Limit: %d | Exceeds: %t\n",
			bs.BlockNumber, bs.BlockType, bs.BlockTime, bs.Structure, bs.TotalQuantity, bs.TotalDuration, bs.LimitDuration, bs.ExceedsLimit)
	}
}
