"// getNextPendingBlockTime returns the earliest pending commercial block time for today.
func getNextPendingBlockTime(t time.Time) (string, error) {
	if DB == nil {
		return "", fmt.Errorf("DB not initialized")
	}
	dateStr := t.Format("2006-01-02")
	var blockTime string
	err := DB.QueryRow(`
		SELECT MIN(block_time) FROM planned_commercial_slots 
		WHERE play_date = $1 AND status = 'PENDING'`, dateStr).Scan(&blockTime)
	if err != nil || blockTime == "" {
		return "", err
	}
	return blockTime, nil
}

// calcCurrentDesvio compares the real clock against the last played item
// to determine how many seconds behind we are.
// Returns positive value = behind schedule.
func calcCurrentDesvio(now time.Time) int {
	blockTime, err := getNextPendingBlockTime(now)
	if err != nil || blockTime == "" {
		return 0
	}

	nowSecs := now.Hour()*3600 + now.Minute()*60 + now.Second()
	var bh, bm, bs int
	_, errScan := fmt.Sscanf(blockTime, "%d:%d:%d", &bh, &bm, &bs)
	if errScan != nil {
		return 0
	}
	blockSecs := bh*3600 + bm*60 + bs

	desvio := nowSecs - blockSecs
	if desvio < 0 {
		return 0
	}
	return desvio
}"

