"// calcCurrentDesvio compares the real clock against the last played item
// to determine how many seconds behind we are.
// Returns positive value = behind schedule.
func calcCurrentDesvio(now time.Time) int {
	if DB == nil {
		return 0
	}

	nowSecs := now.Hour()*3600 + now.Minute()*60 + now.Second()

	// Find the last item played today and when it should end
	todayStr := now.Format("2006-01-02")
	var lastPlayedAt sql.NullString
	var lastDuration sql.NullInt64
	err := DB.QueryRow(
		"SELECT played_at, duration_seconds FROM play_history WHERE played_at >= $1 ORDER BY played_at DESC LIMIT 1",
		todayStr+" 00:00:00",
	).Scan(&lastPlayedAt, &lastDuration)
	if err != nil || !lastPlayedAt.Valid {
		return 0
	}

	// Parse the last played time
	parsedTime, err := time.Parse("2006-01-02 15:04:05", lastPlayedAt.String)
	if err != nil {
		return 0
	}
	lastPlaySecs := parsedTime.Hour()*3600 + parsedTime.Minute()*60 + parsedTime.Second()
	dur := 0
	if lastDuration.Valid {
		dur = int(lastDuration.Int64)
	}
	// Estimate when the last played item will end
	actualEndSecs := lastPlaySecs + dur

	// desvio = current clock time minus the estimated end of the last item
	// If positive and large, it means the clock has moved ahead and we're behind
	desvio := nowSecs - actualEndSecs

	// Only consider positive delays (we can't be "ahead" with this metric)
	if desvio < 0 {
		desvio = 0
	}
	return desvio
}"

