"// expirePastPlannedSlots marks pending slots in the past (older than 15 minutes) as SKIPPED.
func expirePastPlannedSlots(now time.Time) {
	if DB == nil {
		return
	}
	dateStr := now.Format("2006-01-02")
	cutoffTime := now.Add(-15 * time.Minute).Format("15:04:05")

	res, err := DB.Exec(`
		UPDATE planned_commercial_slots 
		SET status = 'SKIPPED' 
		WHERE play_date = $1 AND block_time < $2 AND status = 'PENDING'`, 
		dateStr, cutoffTime)
	if err == nil {
		affected, _ := res.RowsAffected()
		if affected > 0 {
			LogLocal("INFO", "[Scheduler] Expired/skipped %d past commercial slots older than %s", affected, cutoffTime)
		}
	}
}

// GetNextTrack returns the next track for Liquidsoap to play
func GetNextTrack() (string, error) {
	schedMutex.Lock()
	defer schedMutex.Unlock()

	now := time.Now()
	expirePastPlannedSlots(now)"

