"func calcCurrentDesvio(now time.Time) int {
	if lastBlockTime.IsZero() {
		return 0
	}
	// Fetch active schedule to get interval
	schedule, _, err := getActiveScheduleAndBlock(now)
	musicalBlockMins := 8
	if err == nil && schedule != nil && schedule.MusicalBlockDurationMinutes > 0 {
		musicalBlockMins = schedule.MusicalBlockDurationMinutes
	}
	musicSecs := musicalBlockMins * 60

	// Default comm limit
	commLimitSecs := 120
	interval := time.Duration(musicSecs)*time.Second + time.Duration(commLimitSecs)*time.Second

	nextExpectedBlockTime := lastBlockTime.Add(interval)
	if now.After(nextExpectedBlockTime) {
		return int(now.Sub(nextExpectedBlockTime).Seconds())
	}
	return 0
}"

