"package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "c:\\imc-audio-local\\local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	fmt.Println("=== LATEST LOCAL LOGS ===")
	rows, err := db.Query("SELECT timestamp, level, message FROM local_logs ORDER BY timestamp DESC LIMIT 40")
	if err != nil {
		fmt.Println("Error querying local_logs:", err)
	} else {
		defer rows.Close()
		for rows.Next() {
			var ts, lvl, msg string
			_ = rows.Scan(&ts, &lvl, &msg)
			fmt.Printf("[%s] [%s] %s\n", ts, lvl, msg)
		}
	}

	fmt.Println("\n=== PLAY HISTORY (RECENT) ===")
	rowsH, errH := db.Query("SELECT played_at, track_id, track_type, display_name, play_status, planned_block_time FROM play_history ORDER BY played_at DESC LIMIT 20")
	if errH != nil {
		fmt.Println("Error querying play_history:", errH)
	} else {
		defer rowsH.Close()
		for rowsH.Next() {
			var ts, tid, ttype, name, status, planned string
			_ = rowsH.Scan(&ts, &tid, &ttype, &name, &status, &planned)
			fmt.Printf("%s | %s | %s | %s | %s | %s\n", ts, tid, ttype, name, status, planned)
		}
	}
}
"

