"package main

import (
	"fmt"
	"math"
	"time"
)

func main() {
	// Let's mock schedule parameters
	startTimeStr := "07:00:00"
	musicalBlockMins := 8
	commLimitSecs := 120
	interval := time.Duration(musicalBlockMins)*time.Minute + time.Duration(commLimitSecs)*time.Second // 10 minutes (600s)

	var sh, sm, ss int
	_, _ = fmt.Sscanf(startTimeStr, "%d:%d:%d", &sh, &sm, &ss)
	startSecs := sh*3600 + sm*60 + ss
	musicSecs := musicalBlockMins * 60

	// We'll test different startup times
	testTimes := []string{
		"22:04:00", // music block, next comm block at 22:08:00
		"22:07:30", // music block, next comm block at 22:08:00
		"22:07:59", // music block, next comm block at 22:08:00
		"22:08:00", // comm block start, trigger immediately
		"22:09:33", // comm block middle, trigger immediately
		"22:09:59", // comm block end, trigger immediately
		"22:10:00", // music block, next comm block at 22:18:00
		"22:10:15", // music block, next comm block at 22:18:00
	}

