"package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "c:\\imc-audio-local\\local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	var count int
	err = db.QueryRow("SELECT count(*) FROM commercials_and_events WHERE is_downloaded = 1").Scan(&count)
	if err != nil {
		fmt.Println("Error counting commercials:", err)
		return
	}
	fmt.Println("Downloaded commercials count:", count)

	rows, err := db.Query(`
		SELECT name, insertions_per_day, commercial_type 
		FROM commercials_and_events 
		WHERE is_downloaded = 1 
		  AND commercial_type NOT IN ('BLOCK_OPENING','BLOCK_CLOSING','RIGHT_TIME','TEMPERATURE','EVENT')`)
	if err != nil {
		fmt.Println("Error querying commercials:", err)
		return
	}
	defer rows.Close()

	totalInsertions := 0
	for rows.Next() {
		var name, ctype string
		var ins int
		if errScan := rows.Scan(&name, &ins, &ctype); errScan == nil {
			fmt.Printf("- %s [%s]: %d insertions/day\n", name, ctype, ins)
			totalInsertions += ins
		}
	}
	fmt.Println("Total insertions planned per day:", totalInsertions)
}
"

