"package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "c:\\imc-audio-local\\local_cache.db")
	if err != nil {
		fmt.Println("failed to open db:", err)
		os.Exit(1)
	}
	defer db.Close()

	// Update Saturday schedule to start at 00:00:00
	res, err := db.Exec("UPDATE basic_schedules SET start_time = '00:00:00' WHERE id = '03a0a9a0-06a3-4066-9be4-61b5c90ca115'")
	if err != nil {
		fmt.Println("Error updating Saturday start time:", err)
		return
	}
	affected, _ := res.RowsAffected()
	fmt.Printf("Updated %d schedule start time to 00:00:00\n", affected)
}
"

