"// expirePastPlannedSlots marks pending slots in the past (older than 15 minutes) as SKIPPED.
func expirePastPlannedSlots(now time.Time) {
	if DB == nil {
		return
	}
	cutoff := now.Add(-15 * time.Minute)
	cutoffDateStr := cutoff.Format("2006-01-02")
	cutoffTimeStr := cutoff.Format("15:04:05")

	res, err := DB.Exec(`
		UPDATE planned_commercial_slots 
		SET status = 'SKIPPED' 
		WHERE (play_date < $1 OR (play_date = $1 AND block_time < $2)) AND status IN ('PENDING', 'QUEUED')`, 
		cutoffDateStr, cutoffTimeStr)
	if err == nil {
		affected, _ := res.RowsAffected()
		if affected > 0 {
			LogLocal("INFO", "[Scheduler] Expired/skipped %d past commercial slots older than %s %s", affected, cutoffDateStr, cutoffTimeStr)
		}
	}
}"

